package cn.course.community;
import java.util.*;
import java.math.BigDecimal;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import com.fasterxml.jackson.databind.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:publication-flow;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","app.seed=true","app.seed-password=TestOnly!2026Long"})
@AutoConfigureMockMvc @Transactional
class PublicationWorkflowTest {
 @Autowired MockMvc mvc;@Autowired Store s;@Autowired CommunityService domain;@Autowired ObjectMapper json;
 long uid(String n){return s.uid(n+"@example.test");}Map<String,Object> pub(){return s.one("SELECT * FROM publication WHERE submission_id=1");}long id(){return s.id(pub(),"id");}int rev(){return ((Number)pub().get("revision")).intValue();}
 void decide(String who,String action,int revision,String reason,int status)throws Exception{mvc.perform(post("/api/publications/"+id()+"/decisions").with(user(who+"@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(Map.of("action",action,"revision",revision,"reason",reason)))).andExpect(status().is(status));}
 void request(int revision,int status)throws Exception{mvc.perform(post("/api/submissions/1/publication-request").with(user("student@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(Map.of("revision",revision,"reason","已核对课程展示版本")))).andExpect(status().is(status));}
 void pending(){domain.publicationAction(id(),"WITHDRAW",uid("student"));domain.requestPublication(1,uid("student"));}
 List<Map<String,Object>> history(){return (List<Map<String,Object>>)domain.publicationReview(id(),uid("teacher")).get("events");}
 @Test void requestSnapshotsEvaluationAndRecordsActor(){pending();assertEquals("PENDING",pub().get("state"));assertEquals(1,((Number)pub().get("requested_evaluation_revision")).intValue());assertEquals("REQUEST",history().getFirst().get("action_type"));assertEquals("STUDENT",history().getFirst().get("actor_role"));}
 @Test void teacherReturnRequiresReasonAndAuthorCanReapply()throws Exception{pending();decide("teacher","RETURN",rev(),"需要补足教材出处与图注对应的论断",200);assertEquals("RETURNED",pub().get("state"));assertTrue(pub().get("last_reason").toString().contains("教材"));request(rev(),200);assertEquals("PENDING",pub().get("state"));assertTrue(history().stream().anyMatch(h->h.get("action_type").equals("RETURN")));}
 @Test void staleDecisionDoesNotOverwriteOrAppend()throws Exception{pending();int old=rev();decide("teacher","RETURN",old,"先退回",200);int count=history().size();decide("teacher","APPROVE",old,"旧窗口操作",409);assertEquals(count,history().size());assertEquals("RETURNED",pub().get("state"));}
 @Test void duplicateApprovalRejected()throws Exception{pending();decide("teacher","APPROVE",rev(),"核对通过",200);decide("teacher","APPROVE",rev(),"重复通过",409);assertNotNull(pub().get("published_at"));}
 @Test void authorCancellationRetainsGradesAndSubmission()throws Exception{pending();decide("student","WITHDRAW",rev(),"作者撤回申请",200);assertEquals("CANCEL",history().getFirst().get("action_type"));assertNotNull(domain.getEvaluation(1));assertNotNull(domain.submission(1));}
 @Test void authorCannotApproveOrReturn()throws Exception{pending();for(String a:List.of("APPROVE","RETURN"))decide("student",a,rev(),"不得自审",403);}
 @Test void assistantCannotDecideOrReadPrivateHistory()throws Exception{s.db.update("UPDATE course_member SET role='ASSISTANT' WHERE user_id=? AND course_id=1",uid("peer"));decide("peer","WITHDRAW",rev(),"助教不裁定",403);mvc.perform(get("/api/publications/"+id()+"/review").with(user("peer@example.test"))).andExpect(status().isForbidden());}
 @Test void peersAndOtherCourseCannotReadRecords()throws Exception{assertEquals(0,domain.publicationRecords(1,uid("peer")).size());for(String who:List.of("peer","outsider"))mvc.perform(get("/api/publications/"+id()+"/review").with(user(who+"@example.test"))).andExpect(status().isForbidden());mvc.perform(get("/api/courses/1/publication-records").with(user("outsider@example.test"))).andExpect(status().isForbidden());}
 @Test void ownerAndTeacherReadSameFullHistory(){assertEquals(history().size(),((List<?>)domain.publicationReview(id(),uid("student")).get("events")).size());assertEquals(1,domain.publicationRecords(1,uid("teacher")).size());assertEquals(1,domain.publicationRecords(1,uid("student")).size());}
 @Test void publicMetadataDoesNotLeakPrivateReason()throws Exception{domain.publicationAction(id(),"WITHDRAW",uid("teacher"),rev(),"PRIVATE-WITHDRAW-REASON");domain.requestPublication(1,uid("student"),rev(),"PRIVATE-APPLICATION-REASON");domain.publicationAction(id(),"APPROVE",uid("teacher"),rev(),"PRIVATE-APPROVAL-REASON");String list=json.writeValueAsString(domain.publications(1,uid("peer"),false));String detail=json.writeValueAsString(domain.getSubmission(1,uid("peer")));assertFalse(list.contains("PRIVATE-"));assertFalse(detail.contains("PRIVATE-"));assertFalse(detail.contains("publication_event"));}
 @Test void withdrawalRevokesPeerFullRead()throws Exception{mvc.perform(get("/api/submissions/1").with(user("peer@example.test"))).andExpect(status().isOk());decide("teacher","WITHDRAW",rev(),"撤回展示",200);mvc.perform(get("/api/submissions/1").with(user("peer@example.test"))).andExpect(status().isForbidden());assertTrue(domain.publications(1,uid("peer"),false).isEmpty());}
 @Test void regradeAutomaticallyDownsPublicationAndKeepsHistory(){int before=history().size();var items=QualityCalculator.CODES.stream().map(c->new QualityCalculator.Item(c,BigDecimal.valueOf(82),"SCORED","")).toList();domain.evaluate(1,new ApiController.EvaluationRequest(items,"","复评核对",1),uid("teacher"));assertEquals("WITHDRAWN",pub().get("state"));assertEquals(before+1,history().size());assertEquals("REGRADE",history().getFirst().get("action_type"));domain.requestPublication(1,uid("student"));assertEquals(2,((Number)pub().get("requested_evaluation_revision")).intValue());}
 @Test void regradePendingAlsoDownsButWithdrawnDoesNotAppend(){pending();var items=QualityCalculator.CODES.stream().map(c->new QualityCalculator.Item(c,BigDecimal.valueOf(81),"SCORED","")).toList();domain.evaluate(1,new ApiController.EvaluationRequest(items,"","第二次评价",1),uid("teacher"));int count=history().size();domain.evaluate(1,new ApiController.EvaluationRequest(items,"","第三次评价",2),uid("teacher"));assertEquals(count,history().size());assertEquals("WITHDRAWN",pub().get("state"));}
 @Test void ungradedCannotRequestOrCreateRecord()throws Exception{mvc.perform(post("/api/submissions/2/publication-request").with(user("peer@example.test")).with(csrf()).contentType("application/json").content("{\"revision\":0,\"reason\":\"\"}")).andExpect(status().isUnprocessableEntity());assertEquals(0,s.db.queryForObject("SELECT COUNT(*) FROM publication WHERE submission_id=2",Integer.class));}
 @Test void staleReapplicationAndDuplicateRequestRejected()throws Exception{domain.publicationAction(id(),"WITHDRAW",uid("teacher"));request(rev()-1,409);request(rev(),200);request(rev(),409);}
 @Test void csrfAuthenticationAndPayloadValidation()throws Exception{mvc.perform(get("/api/publications/"+id()+"/review")).andExpect(status().isUnauthorized());mvc.perform(post("/api/publications/"+id()+"/decisions").with(user("teacher@example.test")).contentType("application/json").content("{}")).andExpect(status().isForbidden());for(var body:List.of(Map.of("action","RETURN","reason"," ","revision",0),Map.of("action","UNKNOWN","reason","测试","revision",0),Map.of("action","RETURN","reason","测试","revision",-1),Map.of("action","RETURN","reason","测试")))mvc.perform(post("/api/publications/"+id()+"/decisions").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content(json.writeValueAsString(body))).andExpect(status().isBadRequest());}
 @Test void removedAuthorCannotReadOrAct()throws Exception{s.db.update("DELETE FROM course_member WHERE course_id=1 AND user_id=?",uid("student"));mvc.perform(get("/api/publications/"+id()+"/review").with(user("student@example.test"))).andExpect(status().isForbidden());decide("student","WITHDRAW",rev(),"移出后禁止",403);request(rev(),403);}
 @Test void publicationRemainsPinnedAfterDraftEdit(){var before=domain.publications(1,uid("peer"),false).getFirst();s.db.update("UPDATE entry SET title='未发布的新草稿' WHERE id=1");var after=domain.publications(1,uid("peer"),false).getFirst();assertEquals(before.get("title"),after.get("title"));assertEquals(before.get("submission_id"),after.get("submission_id"));}
 @Test void legacyApprovalStillRecordsHistory(){assertEquals("NEW",history().getLast().get("before_state"));pending();domain.publicationAction(id(),"APPROVE",uid("teacher"));assertEquals("APPROVE",history().getFirst().get("action_type"));assertEquals("PUBLISHED",pub().get("state"));}
 @Test void legacyRecordDoesNotInventHistory(){s.db.update("DELETE FROM publication_event WHERE publication_id=?",id());s.db.update("UPDATE publication SET revision=0,requested_evaluation_revision=NULL WHERE id=?",id());assertTrue(history().isEmpty());assertNull(pub().get("requested_evaluation_revision"));}
}
